"use client"
import { useState } from "react"
import { Button } from "rillmark/button"
import { Field } from "rillmark/field"
import { Input } from "rillmark/input"

export default function ComponentDemo() {
  const [email, setEmail] = useState("")
  const [error, setError] = useState("")
  const [saved, setSaved] = useState(false)
  return <form noValidate className="w-full max-w-sm space-y-4" onSubmit={(event) => {
    event.preventDefault()
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
    setError(valid ? "" : "Enter a valid email address, such as maya@example.com.")
    setSaved(valid)
  }}>
    <Field label="Work email" required description="Used for your weekly workspace summary." error={error}><Input type="email" autoComplete="email" value={email} onChange={(event) => { setEmail(event.target.value); setError(""); setSaved(false) }} placeholder="maya@example.com" /></Field>
    <Button type="submit">Save email</Button>
    {saved && <p role="status" className="text-sm text-primary">Email saved for this demo.</p>}
  </form>
}

"use client"
import { useState } from "react"
import { Field } from "rillmark/field"
import { Input } from "rillmark/input"

export default function ComponentDemo() {
  const [query, setQuery] = useState("")
  const projects = ["Coastal restoration", "Spring research", "Watershed atlas"].filter((name) => name.toLowerCase().includes(query.toLowerCase()))
  return <div className="w-full max-w-sm space-y-4">
    <Field label="Find a project" description="Search by project name."><Input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Try coastal…" /></Field>
    <ul className="space-y-2 text-sm">{projects.map((project) => <li key={project}>{project}</li>)}</ul>
    <p role="status" className="text-sm text-muted-foreground">{projects.length ? `${projects.length} projects found` : "No projects match your search."}</p>
  </div>
}

"use client"
import { useId, useState } from "react"
import { Field } from "rillmark/field"
import { RadioGroup, RadioGroupItem } from "rillmark/radio-group"

export default function ComponentDemo() {
  const id = useId()
  const [frequency, setFrequency] = useState("Weekly")
  return <Field label="Summary frequency" description="Choose how often to hear from your workspace.">
    <RadioGroup value={frequency} onValueChange={setFrequency}>{["Daily", "Weekly", "Monthly"].map((value) => <label key={value} htmlFor={`${id}-${value}`} className="flex cursor-pointer items-center gap-2 text-sm"><RadioGroupItem id={`${id}-${value}`} value={value} />{value}</label>)}</RadioGroup>
  </Field>
}

"use client"
import { useState } from "react"
import { Button } from "rillmark/button"
import { Skeleton } from "rillmark/skeleton"

export default function ComponentDemo() {
  const [loading, setLoading] = useState(true)
  return <div className="w-full max-w-sm space-y-5">
    <div aria-busy={loading} className="min-h-28 space-y-3">
      {loading ? <><span className="sr-only" role="status">Loading project preview</span><Skeleton className="h-5 w-2/3" /><Skeleton className="h-4 w-full" /><Skeleton className="h-4 w-5/6" /></> : <><p className="font-semibold">Coastal restoration</p><p className="text-sm text-muted-foreground">12 field notes exploring how our shoreline is changing.</p></>}
    </div>
    <Button variant="outline" onClick={() => setLoading(!loading)}>{loading ? "Show loaded content" : "Preview loading state"}</Button>
  </div>
}

